'use strict'

/**
 * cdpc 6.x 新能力测试台：cluster 模式 + sock 控制通道
 *
 * 运行：node test/test-cluster.js
 *      TEST_PORT=13457 node test/test-cluster.js
 *
 * 覆盖：
 *   cluster 配置规范化与互斥校验 / real_args 包装（exec 字段可见）
 *   workers 异常退出后的自动补员 / launcher 崩溃后整组恢复且不留孤儿
 *   pause-resume 覆盖 launcher 与全部 worker
 *   stop 的三层超时（cdpc 兜底 > launcher 强杀 > worker 收尾）
 *   sock 通道的 ping / has / inspect / load / 控制类操作
 */

process.chdir(__dirname)

const fs = require('node:fs')
const net = require('node:net')
const os = require('node:os')
const {spawnSync} = require('node:child_process')
const cdpc = require('../index')

const PORT = parseInt(process.env.TEST_PORT || '3457', 10)
const WORKDIR = `${os.tmpdir()}/cdpc-cluster-test-${process.pid}`
const SOCKFILE = `${WORKDIR}/cdpcd.sock`

let pass = 0
let fail = 0
const failed = []

function ok(cond, title, extra = '') {
  if (cond) {
    pass += 1
    console.log(`  \x1b[32mPASS\x1b[0m ${title}`)
  } else {
    fail += 1
    failed.push(title)
    console.log(`  \x1b[31mFAIL\x1b[0m ${title}${extra ? '  <' + extra + '>' : ''}`)
  }
}

const sleep = ms => new Promise(rv => setTimeout(rv, ms))
const alive = pid => { try { process.kill(pid, 0); return true } catch (e) { return false } }

function sh(cmd) {
  let r = spawnSync('bash', ['-c', `${cmd} || true`], {encoding: 'utf8', timeout: 10000})
  return (r.stdout || '').trim()
}

/** 轮询直到条件成立，返回是否成立 */
async function until(cond, timeout = 15000, step = 300) {
  let spent = 0
  while (spent < timeout) {
    try { if (await cond()) return true } catch (e) {}
    await sleep(step)
    spent += step
  }
  return false
}

const procState = pid => sh(`awk '{print $3}' /proc/${pid}/stat 2>/dev/null`)
const curl = () => sh(`timeout 2 curl -s http://127.0.0.1:${PORT}/`)

/** 本测试台自己起的 worker（按脚本路径识别，排除 launcher 自身） */
function workerPids() {
  let out = sh(`pgrep -af '${WORKDIR}/web[.]js'`)
  if (!out) return []
  return out.split('\n')
        .filter(l => l && l.indexOf('launcher.js') < 0)
        .map(l => parseInt(l.split(' ')[0], 10))
        .filter(p => p > 0)
}

function launcherPid(cm, name) {
  let chk = cm.find(name)
  return chk && chk.child ? chk.child.pid : 0
}

function preflight() {
  return new Promise(rv => {
    let s = net.createServer()
    s.once('error', err => {
      if (err.code !== 'EADDRINUSE') return rv(`绑定 ${PORT} 失败: ${err.message}`)
      rv(`端口 ${PORT} 已被占用：\n${sh(`ss -ltnp 2>/dev/null | grep ':${PORT} '`) || '(无法确定占用者)'}\n`
        + `换端口：TEST_PORT=13457 node test/test-cluster.js`)
    })
    s.listen(PORT, '0.0.0.0', () => s.close(() => rv('')))
  })
}

function writeFixtures() {
  fs.mkdirSync(WORKDIR, {recursive: true, mode: 0o755})

  // cluster 的 worker：共享监听同一端口，并回报自己的 pid 与 worker 序号
  fs.writeFileSync(`${WORKDIR}/web.js`, [
    "const http = require('http')",
    "const id = process.env.CDPC_WORKER_ID || '?'",
    "process.on('SIGTERM', () => {",
    "  // 留一点收尾时间，用于验证「三层超时」里最内层真的跑得到",
    "  setTimeout(() => process.exit(0), 150)",
    "})",
    `http.createServer((q, s) => s.end(JSON.stringify({pid: process.pid, id})))`,
    `  .listen(${PORT}, '0.0.0.0', () => console.log('worker up', process.pid, 'id=' + id))`
  ].join('\n'))

  // 顽固 worker：完全不理 SIGTERM，用来验证 launcher 的强制终止
  fs.writeFileSync(`${WORKDIR}/stubborn.js`, [
    "const http = require('http')",
    "process.on('SIGTERM', () => console.log(process.pid, '收到 SIGTERM，不退出'))",
    `http.createServer((q, s) => s.end('x')).listen(${PORT + 1}, '0.0.0.0')`
  ].join('\n'))
}

async function main() {
  let err = await preflight()

  if (err) {
    console.error(`\x1b[31m[预检失败]\x1b[0m ${err}`)
    process.exit(1)
  }

  writeFixtures()

  console.log(`主进程 ${process.pid}，测试端口 ${PORT}，工作目录 ${WORKDIR}\n`)

  let warns = []

  const cm = new cdpc({
    stateDir: `${WORKDIR}/state`,
    sockFile: SOCKFILE,
    errorHandle: (e, name) => {
      warns.push(name)
      console.log(`  \x1b[33m[warn]\x1b[0m ${name} ${e && e.message ? e.message : ''}`)
    }
  })

  // ---------------- 配置规范化与互斥校验 ----------------
  console.log('[1] cluster 配置的规范化与互斥校验')

  ok(cm.add({name: 'bad-only', file: `${WORKDIR}/web.js`,
             cluster: true, workers: 2, only: true}) === false,
     'cluster 与 only 互斥，配置被拒绝', cm.lastErrorInfo)

  ok(cm.add({name: 'bad-manual', file: `${WORKDIR}/web.js`,
             cluster: true, workers: 2, real_args: ['x.js']}) === false,
     'cluster 会自动生成 real_args，不允许与手写的叠加', cm.lastErrorInfo)

  ok(cm.add({name: 'bad-cmd', command: 'bash', args: ['-c', 'true'],
             cluster: true, workers: 2}) === false,
     '非 nodejs 命令走不了 cluster，配置被拒绝', cm.lastErrorInfo)

  ok(cm.add({name: 'bad-entry', command: 'node', args: ['-e', 'console.log(1)'],
             cluster: true, workers: 2}) === false,
     '找不到 js 入口文件时拒绝（node -e 这类形式不支持）', cm.lastErrorInfo)

  ok(cm.add({name: 'bad-conflict', file: `${WORKDIR}/web.js`,
             cluster: false, workers: 2}) === false,
     'cluster:false 却写了 workers，属于配置矛盾，拒绝', cm.lastErrorInfo)

  // ---------------- 启动 cluster 服务 ----------------
  console.log('\n[2] cluster 启动：一个 launcher 管 N 个 worker')

  let added = cm.add({
    name: 'web',
    file: `${WORKDIR}/web.js`,
    cluster: true,
    workers: 3,
    restart: 'always',
    restartDelay: 1000,
    options: {stdio: ['ignore', 'ignore', 2]}
  })

  ok(added !== false, 'cluster 服务添加成功')

  cm.monitorStart()

  let up = await until(async () => workerPids().length === 3 && !!curl(), 25000, 500)

  ok(up, `3 个 worker 起来且端口可用（实际 ${workerPids().length} 个）`)

  let chk = cm.find('web')

  ok(chk.workers === 3, 'workers 数量被记录在服务配置上', `workers=${chk.workers}`)
  ok(chk.command === process.execPath || /node/.test(chk.command),
     'command 保持用户写的形态（不因包装而改变语义）', chk.command)
  ok(Array.isArray(chk.real_args) && chk.real_args[0].endsWith('launcher.js'),
     '内部用 real_args 包装成 launcher.js，command 不变', chk.real_args[0])
  ok(chk.real_args.indexOf('--workers') > 0 && chk.real_args.indexOf('--stop-timeout') > 0,
     'launcher 参数里带 --workers 与 --stop-timeout')
  ok(chk.stopTimeout >= 2000,
     'cluster 服务自动放宽 stopTimeout，让 launcher 的有序收尾跑得到',
     `stopTimeout=${chk.stopTimeout}`)

  let launcherStop = parseInt(chk.real_args[chk.real_args.indexOf('--stop-timeout') + 1], 10)

  ok(launcherStop < chk.stopTimeout,
     '三层超时由外到内递减：cdpc 兜底 > launcher 强杀',
     `cdpc=${chk.stopTimeout} launcher=${launcherStop}`)

  // 请求打到不同 worker 上（cluster 的连接分发）
  let hits = new Set()
  for (let i = 0; i < 30; i++) {
    let r = curl()
    try { hits.add(JSON.parse(r).pid) } catch (e) {}
  }

  ok(hits.size >= 2, `连接被分发到多个 worker（命中 ${hits.size} 个）`,
     Array.from(hits).join(','))

  let ids = new Set()
  for (let i = 0; i < 30; i++) {
    let r = curl()
    try { ids.add(JSON.parse(r).id) } catch (e) {}
  }

  ok(Array.from(ids).every(x => x !== '?' && x !== undefined),
     'CDPC_WORKER_ID 注入到了每个 worker（env 是追加而非覆盖）',
     Array.from(ids).join(','))

  // ---------------- 负载：整组的树形聚合 ----------------
  console.log('\n[3] 负载信息：cluster 整组聚合')

  await sleep(2500)
  chk = cm.find('web')

  ok(chk.loadinfo.procCount >= 4,
     '进程树覆盖 launcher + 3 个 worker', `procCount=${chk.loadinfo.procCount}`)
  ok(parseFloat(chk.loadinfo.memTotal) > parseFloat(chk.loadinfo.mem),
     'launcher 自身内存远小于整组 —— 只看自身会严重低估',
     `self=${chk.loadinfo.mem} total=${chk.loadinfo.memTotal}`)

  ok(chk.loadinfo.procs.length >= 4
     && chk.loadinfo.procs.filter(p => /web\.js/.test(p.cmd)).length >= 3,
     'procs 明细里能逐个看到 worker，定位到具体哪个 worker 在吃资源',
     `${chk.loadinfo.procs.length} 条`)

  // ---------------- sock 控制通道 ----------------
  console.log('\n[4] sock 控制通道')

  let listening = await until(async () => {
    try { return fs.lstatSync(SOCKFILE).isSocket() } catch (e) { return false }
  }, 10000, 200)

  ok(listening, 'sock 文件已创建并处于监听状态', SOCKFILE)
  ok((fs.lstatSync(SOCKFILE).mode & 0o777) === 0o600,
     'sock 权限为 0600 —— connect 需要写权限，别的用户连不上',
     '0' + (fs.lstatSync(SOCKFILE).mode & 0o777).toString(8))

  const request = (op, extra = {}) => new Promise((rv, rj) => {
    let conn = net.connect(SOCKFILE)
    let buf = ''
    let timer = setTimeout(() => { conn.destroy(); rj(new Error('sock 超时')) }, 5000)

    conn.on('connect', () => conn.write(JSON.stringify({v: 1, id: 1, op, ...extra}) + '\n'))
    conn.on('data', d => {
      buf += d.toString('utf8')
      let i = buf.indexOf('\n')
      if (i < 0) return
      clearTimeout(timer)
      conn.end()
      try { rv(JSON.parse(buf.slice(0, i))) } catch (e) { rj(e) }
    })
    conn.on('error', e => { clearTimeout(timer); rj(e) })
  })

  let pong = await request('ping')

  ok(pong.ok === true && pong.data.pid === process.pid,
     'ping 返回守护进程自己的 pid', JSON.stringify(pong.data))

  let has = await request('has', {name: 'web'})

  ok(has.ok === true && Array.isArray(has.data) && has.data.length === 1
     && has.data[0].name === 'web' && has.data[0].state === 'RUNNING',
     'has 返回命中服务的摘要（名字、pid、状态）', JSON.stringify(has.data))

  let nohas = await request('has', {name: 'nosuch'})

  ok(nohas.ok === true && Array.isArray(nohas.data) && nohas.data.length === 0,
     'has 对不存在的服务返回空数组而不是报错', JSON.stringify(nohas.data))

  let badname = await request('has', {name: '__proto__'})

  ok(badname.ok === false && badname.error === 'invalid-name',
     '保留字做服务名被拒绝（原型链污染防护）', JSON.stringify(badname))

  let hasAll = await request('has', {name: '__all__'})

  ok(hasAll.ok === true && Array.isArray(hasAll.data) && hasAll.data.length >= 1,
     '__all__ 列出全部服务', `${hasAll.data ? hasAll.data.length : 0} 个`)

  let ins = await request('inspect', {name: 'web'})

  ok(ins.ok === true && ins.data && ins.data.name === 'web',
     'inspect 返回服务详情', ins.data ? Object.keys(ins.data).join(',') : '')

  ok(ins.data.cluster === true && ins.data.workers === 3,
     'inspect 里能看到 cluster 标记与 workers 数量',
     `cluster=${ins.data.cluster} workers=${ins.data.workers}`)
  ok(Array.isArray(ins.data.real_args)
     && ins.data.real_args[0].indexOf('launcher.js') >= 0,
     'inspect 暴露 real_args —— 包装成什么样子对外是可追溯的，不是黑盒',
     ins.data.real_args ? ins.data.real_args.slice(0, 5).join(' ') : '')
  ok(ins.data.cpuTotal !== undefined && ins.data.procs
     && ins.data.procs.length >= 4,
     'inspect 同时给出自身与整组两套指标，以及进程树明细',
     `procs=${ins.data.procs ? ins.data.procs.length : 0}`)

  let st = await request('status')

  ok(st.ok === true && st.data && st.data.pid === process.pid
     && Array.isArray(st.data.childs) && st.data.childs.length >= 1,
     'status 返回守护进程与全部服务的负载快照',
     st.data ? `childs=${st.data.childs.length}` : '')

  // load 是「加载配置文件」，路径校验是安全边界，必须挡住相对路径与不可读路径
  let badPath = await request('load', {path: 'relative/x.json'})

  ok(badPath.ok === false && badPath.error === 'invalid-path',
     'load 拒绝相对路径（只接受绝对路径）', JSON.stringify(badPath))

  let noPath = await request('load', {path: '/nonexistent-cdpc-test.json'})

  ok(noPath.ok === false && noPath.error === 'path-not-readable',
     'load 对不可读路径明确报错，不是静默失败', JSON.stringify(noPath))

  let badop = await request('nosuchop')

  ok(badop.ok === false, '未知操作被明确拒绝而不是静默丢弃', JSON.stringify(badop))

  // ---------------- worker 异常退出后自动补员 ----------------
  console.log('\n[5] worker 异常退出后自动补员')

  let before = workerPids()

  try { process.kill(before[0], 'SIGKILL') } catch (e) {}

  let refilled = await until(async () => {
    let now = workerPids()
    return now.length === 3 && now.indexOf(before[0]) < 0
  }, 20000, 500)

  ok(refilled, `被 SIGKILL 的 worker 被补上，总数回到 3（实际 ${workerPids().length}）`)
  ok(launcherPid(cm, 'web') !== 0 && cm.stateName[cm.find('web').state] === 'RUNNING',
     '补员由 launcher 内部完成，cdpc 侧的服务状态没有抖动')
  ok(!!curl(), '补员期间端口一直可用（其余 worker 继续服务）')

  // ---------------- pause / resume 覆盖整组 ----------------
  console.log('\n[6] pause / resume 覆盖 launcher 与全部 worker')

  let lp = launcherPid(cm, 'web')
  let ws = workerPids()

  cm.pause('web')
  await until(async () => procState(lp) === 'T' && ws.every(p => !alive(p) || procState(p) === 'T'),
              8000, 200)

  ok(procState(lp) === 'T', 'launcher 进入 stopped')
  ok(ws.every(p => !alive(p) || procState(p) === 'T'),
     '全部 worker 也进入 stopped —— 用户看的是一个服务整体，暂停必须覆盖整组',
     ws.map(p => `${p}:${procState(p) || '-'}`).join(' '))
  ok(!curl(), '暂停期间端口不再响应')

  cm.resume('web')

  let back = await until(async () => !!curl(), 10000, 300)

  ok(back, 'resume 后服务恢复响应')
  ok(procState(lp) !== 'T' && ws.every(p => !alive(p) || procState(p) !== 'T'),
     'launcher 与全部 worker 都回到运行态')

  // ---------------- launcher 崩溃：整组恢复且不留孤儿 ----------------
  console.log('\n[7] launcher 崩溃后的整组恢复')

  lp = launcherPid(cm, 'web')
  ws = workerPids()

  try { process.kill(lp, 'SIGKILL') } catch (e) {}

  let noOrphan = await until(async () => ws.every(p => !alive(p)), 10000, 300)

  ok(noOrphan, 'launcher 被强杀后旧 worker 全部自行退出，没有孤儿占着端口',
     `存活 ${ws.filter(alive).length}`)

  let recovered = await until(async () => {
    let now = workerPids()
    return now.length === 3 && launcherPid(cm, 'web') !== lp && !!curl()
  }, 30000, 500)

  ok(recovered, `cdpc 重启整组后恢复（worker=${workerPids().length}）`)
  ok(workerPids().length === 3,
     `worker 数没有翻倍（实际 ${workerPids().length}）—— 旧的没变成孤儿`)

  // ---------------- 通过 sock 做控制类操作 ----------------
  console.log('\n[8] 通过 sock 做控制操作')

  let oldLp = launcherPid(cm, 'web')
  let rst = await request('restart', {name: 'web'})

  ok(rst.ok === true, 'sock 的 restart 被接受', JSON.stringify(rst))

  let restarted = await until(async () => {
    let np = launcherPid(cm, 'web')
    return np !== 0 && np !== oldLp && workerPids().length === 3 && !!curl()
  }, 30000, 500)

  ok(restarted, 'restart 后整组换新并重新绑定端口，无 EADDRINUSE',
     `old=${oldLp} new=${launcherPid(cm, 'web')}`)

  // ---------------- stop：顽固 worker 的强制终止 ----------------
  console.log('\n[9] stop 的分层超时与强制终止')

  ws = workerPids()
  lp = launcherPid(cm, 'web')

  let t0 = Date.now()
  cm.stop('web')

  let allGone = await until(async () => ws.every(p => !alive(p)) && !alive(lp), 15000, 200)
  let cost = Date.now() - t0

  ok(allGone, `stop 把 launcher 与全部 worker 收干净（${cost}ms）`,
     `残留 worker=${ws.filter(alive).length} launcher=${alive(lp) ? 1 : 0}`)
  ok(cost < chk.stopTimeout + 2000,
     `走的是有序收尾而不是等 cdpc 兜底强杀（${cost}ms < ${chk.stopTimeout + 2000}ms）`)

  // 顽固 worker：launcher 必须在自己的阈值内强制终止
  console.log('  · 顽固 worker（完全不理 SIGTERM）')

  cm.add({
    name: 'stub',
    file: `${WORKDIR}/stubborn.js`,
    cluster: true,
    workers: 2,
    restart: 'none',
    options: {stdio: ['ignore', 'ignore', 2]}
  })

  /**
   * 必须排除 launcher 自身：launcher 的命令行是
   * `node .../launcher.js --workers 2 -- .../stubborn.js`，
   * 按脚本路径匹配会把它一起算进来（上一版就因此数出 3 个）。
   */
  const stubWorkers = () => {
    let out = sh(`pgrep -af '${WORKDIR}/stubbor[n].js'`)
    if (!out) return []
    return out.split('\n')
          .filter(l => l && l.indexOf('launcher.js') < 0)
          .map(l => parseInt(l.split(' ')[0], 10))
          .filter(p => p > 0)
  }

  let stubUp = await until(async () => stubWorkers().length === 2, 25000, 500)

  ok(stubUp, `顽固服务的 2 个 worker 起来了（实际 ${stubWorkers().length}）`)

  let stubPids = stubWorkers()
  let stubL = launcherPid(cm, 'stub')

  t0 = Date.now()
  cm.stop('stub')

  let stubGone = await until(async () => stubPids.every(p => !alive(p)) && !alive(stubL),
                             15000, 200)
  cost = Date.now() - t0

  ok(stubGone, `不理 SIGTERM 的 worker 最终被强制终止，零残留（${cost}ms）`,
     `残留 ${stubPids.filter(alive).length}`)

  // ---------------- 收尾 ----------------
  console.log('\n[10] 收尾')

  let tracked = []

  for (let k in cm.childs) {
    let c = cm.childs[k]
    if (c.child && c.child.pid) tracked.push(c.child.pid)
    if (c.loadinfo && Array.isArray(c.loadinfo.procs)) {
      tracked = tracked.concat(c.loadinfo.procs.map(p => p.pid))
    }
  }

  for (let k of Object.keys(cm.childs)) cm.remove(k)

  cm.sockStop && cm.sockStop()
  cm.monitorStop()

  await sleep(2500)

  tracked = tracked.filter((v, i, a) => v && a.indexOf(v) === i)

  ok(tracked.filter(alive).length === 0, 'remove 全部服务后进程零残留',
     `残留 ${tracked.filter(alive).join(',')}`)
  ok(workerPids().length === 0, 'worker 零残留')

  let sockLeft = true
  try { fs.lstatSync(SOCKFILE); sockLeft = true } catch (e) { sockLeft = false }

  ok(!sockLeft, 'sockStop 后 sock 文件被清理，不会让下次启动误判有守护进程在跑')

  cm.killAllChilds(process.pid, 'SIGKILL')
  await sleep(300)
  sh(`rm -rf ${WORKDIR}`)

  console.log(`\n${'='.repeat(52)}`)
  console.log(`通过 ${pass}，失败 ${fail}`)

  if (fail > 0) {
    console.log('失败项：')
    for (let f of failed) console.log(`  - ${f}`)
  }

  console.log('='.repeat(52))

  process.exit(fail > 0 ? 1 : 0)
}

main().catch(e => {
  console.error('测试台异常：', e)
  sh(`rm -rf ${WORKDIR}`)
  process.exit(2)
})
